// Generated by AI
using System;
using System.Text;
using UnityEngine;

/// <summary>
/// A bin that accepts one type of waste. The player deposits by walking close to the bin
/// (automatic) and/or by pressing the deposit key (E) while close. The bin takes only the
/// items of its type from the backpack, one at a time, playing a sound for each piece.
/// Distance is measured to the nearest point of the bin's model, so the pivot position
/// of the model does not matter. No colliders or triggers are needed.
/// </summary>
public class SortingBin : MonoBehaviour
{
    [SerializeField] private WasteType acceptedType;
    [Tooltip("How close (in meters) the player must be to the bin model to deposit.")]
    [SerializeField] private float depositRadius = 3f;
    [SerializeField] private int pointsPerItem = 10;
    [Tooltip("Seconds between each deposited item, so the sound is heard once per piece.")]
    [SerializeField] private float depositInterval = 0.25f;
    [Tooltip("How many items this bin can hold. Shown on the bin label as deposited/capacity.")]
    [SerializeField] private int binCapacity = 10;
    [Tooltip("If on, the bin stops taking items once it is full (they stay in the backpack).")]
    [SerializeField] private bool limitToCapacity = true;

    [Header("Deposit input")]
    [Tooltip("If on, the bin deposits by itself when the player is close.")]
    [SerializeField] private bool autoDeposit = true;
    [Tooltip("Pressing this key near the bin also deposits (works even if auto deposit is off).")]
    [SerializeField] private KeyCode depositKey = KeyCode.E;
    [Tooltip("Gamepad alternative to the deposit key (X button on most controllers).")]
    [SerializeField] private KeyCode gamepadDepositButton = KeyCode.JoystickButton2;

    [Header("Feedback")]
    [SerializeField] private AudioSource audioSource;
    [SerializeField] private AudioClip correctClip;
    [SerializeField] private AudioClip wrongClip;
    [Tooltip("Plays the wrong clip when the player arrives carrying waste but nothing this bin accepts.")]
    [SerializeField] private bool playWrongBinSound = false;

    [Header("Debug")]
    [Tooltip("Prints in the Console what this bin sees (distance, backpack contents).")]
    [SerializeField] private bool logDebug = false;

    // The HUD can subscribe to these events to update the score and show messages.
    public static event Action<int> OnScoreChanged;               // score delta
    public static event Action<bool, WasteType> OnWasteDeposited; // was it correct, which type

    // Per-bin counter, used by BinCounterLabel to fill the "0/10" text on the bin.
    public event Action<int, int> OnCountChanged;                 // deposited, capacity
    public int DepositedCount { get; private set; }
    public int BinCapacity => binCapacity;

    private BackpackInventory inventory;
    private Renderer[] renderers;
    private bool playerInRange;
    private bool keyHeldMode;
    private float nextDepositTime;
    private float nextDistanceLogTime;

    private void Awake()
    {
        if (audioSource == null)
        {
            audioSource = GetComponent<AudioSource>();
        }

        renderers = GetComponentsInChildren<Renderer>();
    }

    private void Start()
    {
        inventory = FindAnyObjectByType<BackpackInventory>();
        if (inventory == null)
        {
            Debug.LogError("SortingBin '" + name + "': no BackpackInventory found in the scene. " +
                           "Add the BackpackInventory component to the player.", this);
            return;
        }

        if (logDebug)
        {
            Debug.Log("SortingBin '" + name + "' is active. Accepts " + acceptedType +
                      ", radius " + depositRadius + ", key " + depositKey + ".", this);
        }
    }

    private void Update()
    {
        if (inventory == null) return;

        float distance = DistanceToPlayer();
        bool inRange = distance <= depositRadius;

        if (logDebug && Time.time >= nextDistanceLogTime && distance <= depositRadius * 3f)
        {
            nextDistanceLogTime = Time.time + 1f;
            Debug.Log("SortingBin '" + name + "' distance to player: " + distance.ToString("F1") +
                      " m (radius " + depositRadius + ")", this);
        }

        if (inRange && !playerInRange)
        {
            OnPlayerArrived();
        }

        playerInRange = inRange;

        if (!inRange) return;

        // Pressing the key near the bin starts a deposit even if auto deposit is off.
        if (Input.GetKeyDown(depositKey) || Input.GetKeyDown(gamepadDepositButton))
        {
            keyHeldMode = true;
        }

        if (!autoDeposit && !keyHeldMode) return;
        if (Time.time < nextDepositTime) return;
        if (limitToCapacity && DepositedCount >= binCapacity) return; // Bin is full.

        if (!inventory.TryTake(acceptedType))
        {
            keyHeldMode = false; // Nothing left of this type.
            return;
        }

        nextDepositTime = Time.time + depositInterval;
        DepositedCount++;
        OnCountChanged?.Invoke(DepositedCount, binCapacity);

        PlaySound(correctClip);
        OnScoreChanged?.Invoke(pointsPerItem);
        OnWasteDeposited?.Invoke(true, acceptedType);
    }

    // Distance on the ground plane from the player to the nearest point of this bin's model.
    private float DistanceToPlayer()
    {
        Vector3 player = inventory.transform.position;

        if (renderers != null && renderers.Length > 0)
        {
            Bounds bounds = new Bounds(renderers[0].bounds.center, Vector3.zero);
            foreach (Renderer r in renderers)
            {
                bounds.Encapsulate(r.bounds);
            }

            Vector3 closest = bounds.ClosestPoint(new Vector3(player.x, bounds.center.y, player.z));
            Vector3 offset = player - closest;
            offset.y = 0f;
            return offset.magnitude;
        }

        Vector3 fallback = player - transform.position;
        fallback.y = 0f;
        return fallback.magnitude;
    }

    private void OnPlayerArrived()
    {
        if (logDebug)
        {
            Debug.Log("Player reached bin '" + name + "' (accepts " + acceptedType + ") | Backpack: " +
                      DescribeBackpack(), this);
        }

        if (playWrongBinSound &&
            inventory.GetAmount(acceptedType) == 0 &&
            CarriesAnyWaste())
        {
            PlaySound(wrongClip);
        }
    }

    private bool CarriesAnyWaste()
    {
        foreach (WasteType type in Enum.GetValues(typeof(WasteType)))
        {
            if (inventory.GetAmount(type) > 0) return true;
        }

        return false;
    }

    private string DescribeBackpack()
    {
        StringBuilder builder = new StringBuilder();
        foreach (WasteType type in Enum.GetValues(typeof(WasteType)))
        {
            builder.Append(type).Append(' ').Append(inventory.GetAmount(type)).Append("  ");
        }

        return builder.ToString();
    }

    private void PlaySound(AudioClip clip)
    {
        if (audioSource != null && clip != null)
        {
            audioSource.PlayOneShot(clip);
        }
    }

    private void OnDrawGizmosSelected()
    {
        Gizmos.color = Color.green;
        Gizmos.DrawWireSphere(transform.position, depositRadius);
    }
}
